// VAPI sends tool calls to this n8n webhook. Normalise the payload.
const root = $input.first().json;
const body = root.body ?? root;
const message = body.message ?? {};
const toolCalls = message.toolCalls ?? message.toolCallList ?? [];

if (!toolCalls.length) {
  // Not a tool call (status update / transcript / end-of-call). Nothing to do.
  return [{ json: { toolName: 'none', toolCallId: null, args: {} } }];
}

const call = toolCalls[0];
const fn = call.function ?? {};
let args = fn.arguments ?? {};
if (typeof args === 'string') {
  try { args = JSON.parse(args); } catch (e) { args = {}; }
}

return [{ json: { toolCallId: call.id, toolName: fn.name, args } }];

// ─── CONFIGURE ────────────────────────────────────────────────────────────
const TZ          = 'Europe/London';
const OPEN_HOUR   = 9;      // 09:00
const CLOSE_HOUR  = 17;     // 17:00
const SLOT_MINS   = 30;     // appointment length
const DAYS_AHEAD  = 7;      // how far to look
const MAX_SLOTS   = 3;      // slots to offer
const WORK_DAYS   = [1,2,3,4,5];   // 1=Mon … 7=Sun
const MIN_NOTICE_HOURS = 1;
// ─── END CONFIGURE ────────────────────────────────────────────────────────

// Busy intervals from the calendar (Get Calendar Events output).
const events = $input.all().map(i => i.json).filter(e => e && e.start);
const busy = events.map(e => ({
  start: DateTime.fromISO(e.start.dateTime || e.start.date, { zone: TZ }),
  end:   DateTime.fromISO(e.end.dateTime   || e.end.date,   { zone: TZ }),
}));
const overlaps = (s, e) => busy.some(b => s < b.end && e > b.start);

const now = $now.setZone(TZ);
const notBefore = now.plus({ hours: MIN_NOTICE_HOURS });
const start = now.startOf('day');
const slots = [];

for (let d = 0; d <= DAYS_AHEAD && slots.length < MAX_SLOTS; d++) {
  const day = start.plus({ days: d });
  if (!WORK_DAYS.includes(day.weekday)) continue;
  let found = false;
  for (let h = OPEN_HOUR; h < CLOSE_HOUR && !found; h++) {
    for (let m = 0; m < 60 && !found; m += SLOT_MINS) {
      const s = day.set({ hour: h, minute: m, second: 0, millisecond: 0 });
      const e = s.plus({ minutes: SLOT_MINS });
      if (s <= notBefore) continue;
      if (e.hour > CLOSE_HOUR) continue;
      if (overlaps(s, e)) continue;
      slots.push(s);
      found = true;               // one slot per day → nicer spread
    }
  }
}

const toolCallId = $('Parse Vapi Tool Call').first().json.toolCallId;
let result;
if (!slots.length) {
  result = "No open slots in the next week. Ask the caller for a preferred day and let them know the team will confirm by text.";
} else {
  const lines = slots.map((s, i) =>
    `${i + 1}. ${s.toFormat("cccc d LLLL 'at' h:mm a")}  (id: ${s.toISO()})`
  );
  result = `Available appointment slots:\n${lines.join('\n')}\n\n` +
    `Offer these to the caller naturally. When they pick one, call bookAppointment ` +
    `with startTime set to the EXACT id (ISO) shown above for the chosen slot.`;
}

return [{ json: { results: [{ toolCallId, result }] } }];

// Build the VAPI tool response for a completed booking.
const parse = $('Parse Vapi Tool Call').first().json;
const args = parse.args || {};
const toolCallId = parse.toolCallId;

let human = args.startTime;
try {
  human = DateTime.fromISO(args.startTime).setZone('Europe/London')
            .toFormat("cccc d LLLL 'at' h:mm a");
} catch (e) {}

const result = `Booking confirmed for ${args.customerName || 'the caller'} on ${human}. ` +
  `Tell the caller it is booked and they will receive a confirmation shortly.`;

return [{ json: { results: [{ toolCallId, result }] } }];

// Build the Vapi tool response after a message is taken.
const parse = $('Parse Vapi Tool Call').first().json;
const result = 'Message taken and passed to the team. Tell the caller someone will ring them back as soon as possible.';
return [{ json: { results: [{ toolCallId: parse.toolCallId, result }] } }];

// Vapi also posts status updates, transcripts and end-of-call reports to this
// webhook. They are not tool calls, so acknowledge them and do nothing.
return [{ json: { results: [] } }];
